ids = await orders_list_order_ids()
futures = [orders_get_order(order_id=i) for i in ids]
rows = [await f for f in futures]
totals = {}
statuses = {}
bad = []
for r in rows:
    if not isinstance(r.get("amount"), (int, float)) or r.get("region") is None:
        bad.append(r.get("order_id"))
        continue
    totals[r["region"]] = totals.get(r["region"], 0) + r["amount"]
    statuses[r.get("status")] = statuses.get(r.get("status"), 0) + 1
return {
    "n_ids": len(ids),
    "unique_ids": len(set(ids)),
    "n_rows": len(rows),
    "statuses": statuses,
    "bad": bad,
    "totals": {k: round(v, 2) for k, v in sorted(totals.items())},
}

